    'Sesión activa'::text AS detalle,
    'success'::text AS tipo,
    to_char(fec_ultimo_acceso, 'DD/MM/YYYY HH24:MI'::text) AS tiempo
   FROM public.tbl_usuarios u
  WHERE ((bol_activo = true) AND (fec_ultimo_acceso IS NOT NULL))
